from __future__ import annotations

REVIEW_UI_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SCEI · Review Queue</title>
<style>:root{--bg:#f5f7fb;--panel:#fff;--ink:#172033;--muted:#667085;--line:#e4e8ef;--brand:#176b87;--good:#147a5b;--bad:#b42318;--shadow:0 12px 30px #183b4d12}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,sans-serif}.shell{max-width:1100px;margin:auto;padding:28px 20px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;color:var(--brand);font-size:11px;font-weight:800}.top h1{margin:4px 0;font-size:25px}.card{background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);padding:18px;margin-bottom:14px}.toolbar{display:grid;grid-template-columns:1fr 180px auto;gap:10px}.toolbar input,.toolbar select,.toolbar button{font:inherit;padding:10px;border:1px solid #cbd3dd;border-radius:8px;background:#fff}.toolbar button{background:var(--brand);color:#fff;border:0;font-weight:700;cursor:pointer}.review{display:grid;gap:15px}.review-head{display:flex;justify-content:space-between;gap:12px}.review-head h2{margin:0;font-size:17px}.pill{background:#fff4df;color:#a66300;border-radius:99px;padding:4px 9px;font-size:11px;font-weight:700}.meta{color:var(--muted);font-size:12px}.candidate{display:flex;justify-content:space-between;align-items:center;border:1px solid var(--line);border-radius:10px;padding:12px;gap:12px}.candidate.selected{border:2px solid var(--brand);background:#f0fafb}.candidate button,.actions button{border:0;border-radius:7px;padding:8px 11px;cursor:pointer;font-weight:700}.choose{background:#e8f3f6;color:var(--brand)}.approve{background:var(--good);color:#fff}.reject{background:#fff0ee;color:var(--bad);border:1px solid #f2c8c3!important}.apply{background:var(--brand);color:#fff}.empty{text-align:center;color:var(--muted);padding:40px}.status{margin:12px 0;color:var(--muted)}pre{white-space:pre-wrap;background:#101b26;color:#d4e7ed;padding:12px;border-radius:8px;font-size:11px}@media(max-width:700px){.toolbar{grid-template-columns:1fr}.review-head,.candidate{display:block}.candidate button{margin-top:8px}}</style></head>
<body><div class="shell"><div class="top"><div><div class="eyebrow">Evidence intelligence</div><h1>Resolution review queue</h1><div class="meta">Review ambiguous identifiers before they become graph relationships.</div></div><a href="/ui">← Investigation console</a></div>
<section class="card"><div class="toolbar"><input id="org" placeholder="Organization UUID" required><select id="status"><option value="pending">Pending reviews</option><option value="approved">Approved</option><option value="application_failed">Application failed</option><option value="applied">Applied</option><option value="rejected">Rejected</option></select><button id="load">Load queue</button></div><div id="statusText" class="status">Enter an organization ID to load reviews.</div></section><main id="queue"></main></div>
<script>const $=x=>document.getElementById(x);let reviews=[];async function api(url,o){const r=await fetch(url,o),d=await r.json();if(!r.ok)throw Error(d.detail||r.statusText);return d}function render(){if(!reviews.length){$('queue').innerHTML='<section class="card empty">No reviews in this queue.</section>';return}$('queue').innerHTML=reviews.map((r,i)=>`<section class="card review"><div class="review-head"><div><h2>${r.field_name}: ${r.observed_value}</h2><div class="meta">Review ${r.review_id} · Event ${r.event_id}<br>${r.rationale}</div></div><span class="pill">${r.status}</span></div><div>${(r.candidates||[]).map((c,j)=>`<div class="candidate ${r._selected===c.entity_id?'selected':''}"><div><b>${c.entity_id}</b><div class="meta">Score ${c.score??'—'} · ${c.state??'candidate'}</div></div><button class="choose" onclick="choose(${i},'${c.entity_id}')">${r._selected===c.entity_id?'Selected':'Select candidate'}</button></div>`).join('')}</div><div id="ai-${i}" class="meta"></div><div class="actions"><button class="choose" onclick="assist(${i})">Ask AI · advisory</button><button class="approve" onclick="decide(${i},'approve')">Approve selected</button><button class="reject" onclick="decide(${i},'reject')">Reject</button><input id="ctx-${i}" placeholder="Context UUID for apply" style="padding:8px;border:1px solid #cbd3dd;border-radius:7px"><button class="apply" onclick="apply(${i})">Apply decision</button></div></section>`).join('')}function choose(i,id){reviews[i]._selected=id;render()}async function load(){try{const org=$('org').value.trim();if(!org)throw Error('Organization ID is required');const d=await api(`/v1/reviews/resolution?organization_id=${encodeURIComponent(org)}&status=${$('status').value}`);reviews=d.results;$('statusText').textContent=`Loaded ${reviews.length} review(s).`;render()}catch(e){$('statusText').textContent=e.message;$('queue').innerHTML=''}}async function assist(i){try{const r=reviews[i],box=$(`ai-${i}`);box.textContent='Requesting grounded advisory analysis…';const d=await api(`/v1/reviews/resolution/${r.review_id}/assistance?organization_id=${encodeURIComponent($('org').value)}`,{method:'POST'});box.innerHTML=`<b>AI advisory · ${d.recommendation} · ${(d.confidence*100).toFixed(0)}%</b><br>${d.rationale}<br><small>${d.citations.length} grounded citation(s). ${d.warning||''} Advisory only; reviewer action is still required.</small>`}catch(e){$(`ai-${i}`).textContent=`AI assistance unavailable: ${e.message}`}}async function decide(i,action){try{const r=reviews[i];if(action==='approve'&&!r._selected)throw Error('Select a candidate first');const d=await api(`/v1/reviews/resolution/${r.review_id}?organization_id=${encodeURIComponent($('org').value)}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,reviewer_id:'local-reviewer',selected_entity_id:r._selected||null})});reviews[i]=d;$('statusText').textContent=`Review ${r.review_id} is ${d.status}.`;render()}catch(e){$('statusText').textContent=e.message}}async function apply(i){try{const r=reviews[i],ctx=$(`ctx-${i}`).value.trim();if(!ctx)throw Error('A projection context is required');const d=await api(`/v1/reviews/resolution/${r.review_id}/apply?organization_id=${encodeURIComponent($('org').value)}&context_id=${encodeURIComponent(ctx)}`,{method:'POST'});$('statusText').textContent=`Applied: ${d.events_reprojected} event(s), ${d.edges_written} edge(s).`;await load()}catch(e){$('statusText').textContent=e.message}}$('load').onclick=load;window.choose=choose;window.decide=decide;window.apply=apply;window.assist=assist;</script></body></html>'''
